// === Tab: mySketch ===
let organisms = [];
let r = 0.005;
let step = 20;
let org_n = 40;

let showOrganisms;
let showPaths;
let showEnvironment;
let strictness;
let mutations;
let ECS; // SPEED OF ENVIRONMENTAL CHANGES

function randomPath(n) {
	let path = [];
	let R = random(100);
	let r1 = random(windowWidth);
	let r2 = random(windowHeight);
	let R1 = random(windowWidth*0.2, windowWidth*0.8);
	let R2 = random(windowHeight*0.2, windowHeight*0.8);
	for (let i = 0; i < n; i++) {
		path.push({'x': (noise(i*0.2+R)-0.5)*r1 + R1, 'y': (noise(i*0.2+R+0.5)-0.5)*r2 + R2});
	}
	return path;
}

function randomColor() {
	return {'r': floor(random(255)), 'g': floor(random(255)), 'b': floor(random(255))}
}

function foodAt(x, y) {
	return sin(sin((noise(x*r, y*r, millis()*ECS) - 0.5)*PI)*HALF_PI)*0.5+0.5;
}

class Organism {
	constructor(dir = random(TWO_PI), path = randomPath(floor(random(2, 10))), x = -1000, y = -1000, color = randomColor(), size = random(8, 30),
							accuracy = random(0.8, 0.95), speed = 0, maxSpeed = random(2, 8), acceleration = random(0.03, 0.1), turningStrength = 0.07, cycle = 0) {
		this.path = JSON.parse(JSON.stringify(path));
		this.accuracy = accuracy;
		this.speed = speed;
		this.maxSpeed = maxSpeed;
		if (x == -1000) {
			this.x = path[0].x;
			this.y = path[0].y;
		}
		else {
			this.x = x;
			this.y = y;
		}
		this.dir = dir;
		this.cycle = cycle;
		this.turnS = turningStrength;
		this.closeEnough = 0.2/acceleration*10;
		this.a = acceleration;
		this.ogdist = 0;
		this.speeding = 1;
		this.color = color;
		this.hp = 1000;
		this.gaveBirth = 0;
		this.size = size;
	}

	lookToward(x, y) {
		return atan2(y - this.y, x - this.x);
	}

	distanceTo(x, y) {
		return sqrt((x - this.x)*(x - this.x) + (y - this.y)*(y - this.y));
	}

	distanceToGoal() {
		return this.distanceTo(this.path[this.cycle].x, this.path[this.cycle].y);
	}

	drawPath () {
		textSize(20);
		strokeWeight(2);
		stroke(this.color.r, this.color.g, this.color.b);
		for (let i = 0; i < this.path.length; i++) {
			//text(i+1, this.path[i].x, this.path[i].y);
			line(this.path[i].x, this.path[i].y, this.path[(i+1)%this.path.length].x, this.path[(i+1)%this.path.length].y);
		}
	}

	mutateColor() {
		var r = this.color.r;
		let g = this.color.g;
		let b = this.color.b;
		var R = randomColor();
		let c = random(0.8*mutations);
		return {'r': R.r*c + r*(1-c), 'g': R.g*c + g*(1-c), 'b': R.b*c + b*(1-c)}
	}

	mutate(what, a = 0.4*mutations) {
		return what*random(1-a, 1+a);
	}

	mutatePath(plus = random(5*mutations), minus = random(5*mutations), change = random(50*mutations)) {
		let newPath = [...this.path];
		for (let i = 0; i < floor(plus); i++) {
			newPath.splice(floor(random(newPath.length-0.5)), 1);
		}
		for (let i = 0; i < floor(minus); i++) {
			newPath.push({'x': this.x + random(-8, 8)*change, 'y': this.y + random(-8, 8)*change});
		}
		for (let i = 0; i < newPath.length; i++) {
			newPath[i].x += random(-1, 1)*change;
			newPath[i].y += random(-1, 1)*change;
		}
		return newPath;
	}

	giveBirth(organisms) {
		let np = this.mutatePath();
		organisms.push(new Organism(this.dir, np, this.x, this.y, this.mutateColor(), this.mutate(this.size, random(0, mutations)),
																this.mutate(this.accuracy, 0.8*mutations), this.speed*0.7, this.mutate(this.maxSpeed),
																this.mutate(this.a), this.mutate(this.turnS), this.cycle%np.length))
	}

	step (organisms) {

		if (this.path.length == 0) return 1;

		this.hp -= (1-foodAt(this.x, this.y))*strictness;

		if (this.distanceToGoal() <= this.closeEnough) {
			this.cycle = (this.cycle + 1)%this.path.length;
			this.ogdist = this.distanceToGoal();
		}
		if (this.distanceToGoal() > this.ogdist) {
			this.ogdist = this.distanceToGoal();
			this.speeding = -1;
		}
		if (this.distanceToGoal()/this.ogdist < 0.2) {
			this.speeding = -0.25;
		}
		if (this.speed == 0 && this.speeding == -1 && this.distanceToGoal() > this.closeEnough) {
			this.speeding = 1;
		}
		let diff = (this.lookToward(this.path[this.cycle].x, this.path[this.cycle].y) - this.dir + PI)%TWO_PI - PI;
		this.dir += diff*this.turnS +
								random(-PI, PI)*(1-this.accuracy)*this.distanceToGoal()/this.ogdist;
		this.speed += this.speeding*this.a;
		this.speed = max(min(this.speed, this.maxSpeed), 0);
		if (this.speed == 0) this.speeding = 1;
		this.x += cos(this.dir)*this.speed;
		this.y += sin(this.dir)*this.speed;

		if (random(1)<0.003 && this.gaveBirth < 2 && this.hp < 800) {
			this.giveBirth(organisms);
			this.gaveBirth +random(1,31);
		}


		fill(this.color.r, this.color.g, this.color.b);
		if (showPaths) this.drawPath();
		stroke((1-this.hp/1000)*255);
		strokeWeight(2);
		if (showOrganisms) circle(this.x, this.y, this.size);
		//stroke(0);
		//text(floor(this.hp), this.x, this.y);

		if (this.hp <= 0) return 1;
		return 0;

	}
}



function setup() {
	createCanvas(windowWidth, windowHeight);
	for (let i = 0; i < org_n; i++) {
		organisms.push(new Organism());
	}

	showOrganisms_s = createSlider(0, 1, 1);
	showOrganisms_s.position(10, 30);

	showPaths_s = createSlider(0, 1, 1);
	showPaths_s.position(10, 70);

	showEnvironment_s = createSlider(0, 1, 1);
	showEnvironment_s.position(10, 110);

	strictness_s = createSlider(0.5, 10, 4);
	strictness_s.position(10, 150);

	mutations_s = createSlider(0, 1000, 250,100,50);
	mutations_s.position(10, 190);

	ECS_s = createSlider(0, 100, 2);
	ECS_s.position(10, 230);
}

function drawEnvironment() {

	for (let i = 0; i <= windowWidth; i += step) {
		for (let j = 0; j <= windowHeight; j += step) {
			strokeWeight(foodAt(i, j)*step);
			stroke(100);
			point(i, j);
		}
	}

}

function texts() {
	fill(255);
	stroke(0);
	text('Show Organisms', 10, 30);
	text('Show Paths', 10, 70);
	text('Show Environment', 10, 110);
	text('Strictness', 10, 150); text(strictness, 130, 150);
	text('Mutations', 10, 190); text(mutations, 130, 190);
	text('Environmental Changes Over Time', 10, 230); text(ECS, 250, 210);
}

function draw() {
	showOrganisms = showOrganisms_s.value();
	showPaths = showPaths_s.value();
	showEnvironment = showEnvironment_s.value();
	strictness = strictness_s.value();
	mutations = mutations_s.value()/1000;
	ECS = ECS_s.value()/100000;

	background(0.2*255);
	if (showEnvironment) drawEnvironment();
	for (let i = 0; i < organisms.length; i++) {
		if (organisms[i].step(organisms)) {
			organisms.splice(i, 1);
			i--;
		}
	}

	texts();
	//fill ('#FF0000');
	//text(org.cycle+1, 10, 20);
	//text(org.dir*180/PI, 10, 40);
}

